<?php
declare(strict_types=1);
$root=dirname(__DIR__,2);require $root.'/runtime-loader.php';(new AigcRuntimeApp($root))->initialize();
set_exception_handler(static function(Throwable $error):void{fwrite(STDERR,$error->getMessage().PHP_EOL);exit(1);});
use app\common\service\decorate\agent\{DecorationAgentService as S,DecorationAgentDecision as D};
$n=0;function guidanceCheck(bool $ok,string $label): void {global $n;if(!$ok)throw new RuntimeException($label);$n++;}
$method=new ReflectionMethod(S::class,'visualReviewContext');$method->setAccessible(true);
$context=['visual_review'=>['screenshot_width'=>750,'screenshot_height'=>1446],'approved_design'=>['run_id'=>99,'revision'=>3,'hash'=>str_repeat('a',64),'asset'=>['width'=>768,'height'=>1376],'blueprint'=>['regions'=>[['components'=>[['name'=>'title-bar','content'=>['font_size'=>14]]]]]]]];
$guide=$method->invoke(null,$context);
guidanceCheck($guide['image_order']===['图1：已确认设计稿（target）','图2：实际候选截图（actual）'],'visual context matches the actual target-first transport order');
guidanceCheck($guide['image_dimensions']['logical_width_px']===375&&$guide['image_dimensions']['approved_design']['width_px']===768&&$guide['image_dimensions']['actual_capture']['width_px']===750,'uses authoritative raster dimensions rather than blueprint layout numbers');
guidanceCheck($guide['image_dimensions']['approved_design']['to_logical_px_scale']===375/768&&$guide['image_dimensions']['actual_capture']['to_logical_px_scale']===0.5,'normalizes each real image independently onto the logical mobile width');
guidanceCheck($guide['image_dimensions']['approved_design']['source']===['width_px'=>768,'height_px'=>1376]&&$guide['image_dimensions']['approved_design']['model_input']===['width_px'=>375,'height_px'=>672,'to_logical_px_scale'=>1],'approved source identity dimensions remain distinct from actual equal-width model transport');
guidanceCheck($guide['image_dimensions']['actual_capture']['model_input']===['width_px'=>375,'height_px'=>723,'to_logical_px_scale'=>1],'actual capture uses the same transport width without cropping different full-page heights');
guidanceCheck(str_contains($guide['image_dimensions']['units'],'不要再对副本乘原图scale')&&str_contains($guide['image_dimensions']['units'],'墨迹bbox高度不等于CSS font_size')&&str_contains($guide['image_dimensions']['units'],'不能据此宣称PASS'),'review cannot double-scale copies, equate glyph ink to CSS font size, or infer acceptance merely from normalization');
guidanceCheck($guide['target']['revision']===3&&$guide['target']['hash']===$context['approved_design']['hash']&&!isset($guide['target']['blueprint']),'visual target is exact latest approved image identity, not prior proposed parameter values');
guidanceCheck(str_contains($guide['priority'],'批准图片优先')&&str_contains($guide['priority'],'不是视觉批准规范'),'prior blueprint and historical statements cannot override the visual reference');
guidanceCheck(count($guide['region_checks'])>=5&&str_contains(implode(' ',$guide['region_checks']),'可见bbox'),'requires region-level geometry, typography and visible glyph bounds evidence');
$validation=$guide['server_validation_contract']??[];
guidanceCheck(($validation['candidate_binding']['field']??'')==='candidate_hash'&&str_contains($validation['candidate_binding']['object']??'','完整候选')&&str_contains($validation['candidate_binding']['checks']??'','revision'),'candidate hash is a server-owned exact candidate tuple check');
guidanceCheck(($validation['draft_concurrency']['field']??'')==='expected_hash'&&str_contains($validation['draft_concurrency']['comparison']??'','不与candidate_hash比较'),'draft concurrency hash is independent of candidate content hash');
guidanceCheck(str_contains($validation['capture_evidence']['meaning']??'','capture_attested=false')&&str_contains($validation['capture_evidence']['meaning']??'','不表示PNG无效')&&str_contains($validation['capture_evidence']['limit']??'','不证明真实DOM'),'client-capture limitation neither invents DOM attestation nor automatically rejects valid PNG evidence');
$unknown=$context;unset($unknown['approved_design']['asset']['width']);guidanceCheck($method->invoke(null,$unknown)['image_dimensions']['approved_design']['to_logical_px_scale']===null,'unknown image width never creates invented measurement');
guidanceCheck($method->invoke(null,[])===null,'ordinary conversations gain no visual-review target');
$prompt=D::prompt();guidanceCheck(str_contains($prompt,'批准图片优先')&&str_contains($prompt,'估算')&&str_contains($prompt,'旧蓝图'),'decision prompt explicitly treats measurements as estimates and prior parameters as subordinate');
guidanceCheck(str_contains($prompt,'图1是已确认设计稿（target）')&&str_contains($prompt,'图2是实际候选截图（actual）')&&str_contains($prompt,'禁止把两图反置'),'system instruction names both image roles and avoids reversed correction direction');
guidanceCheck(str_contains(D::visualReviewInstruction(),'服务端已将两张送审副本完整等宽375')&&str_contains(D::visualReviewInstruction(),'直接比较model_input')&&str_contains(D::visualReviewInstruction(),'不可二次缩放')&&str_contains(D::visualReviewInstruction(),'墨迹bbox')&&str_contains(D::visualReviewInstruction(),'CSS字号'),'decision instruction agrees with equal-width wire copies and compares like-for-like visible glyphs rather than CSS font values');
guidanceCheck(str_contains($prompt,'可见bbox')&&str_contains($prompt,'独立图标')&&str_contains($prompt,'重新截图'),'review checks real visible image/glyph composition and requires a new screenshot after repair');
guidanceCheck(str_contains($prompt,'每轮')&&str_contains($prompt,'修复final也必须返回acceptance')&&!str_contains($prompt,'只有未发生任何编辑/生图、各类证据充分时才返回acceptance'),'every repair round retains six-category diagnosis instead of suppressing acceptance');
guidanceCheck(str_contains($prompt,'不要求这两个哈希相等')&&str_contains($prompt,'capture_attested=false')&&str_contains($prompt,'不能仅因该值为false')&&str_contains($prompt,'最终版本、费用和应用许可仍由服务端硬校验决定'),'review instruction prohibits fabricated hash-equality/DOM-attestation gates while preserving server authority');
$checks=array_map(fn($category)=>['category'=>$category,'passed'=>false,'detail'=>'本轮输入旧截图的target/actual存在差异；本轮修复效果尚未验证。','evidence'=>['对应区域的具体target/actual对照']],['layout','typography','color','assets','icons','interaction']);
$diagnosis=['passed'=>false,'checks'=>$checks,'summary'=>'本轮只诊断输入原图，修复后需重新截图'];
$parsed=D::parse(S::json(['reply'=>'已生成修复候选，效果待截图验证','kind'=>'final','operations'=>[['type'=>'configure_page','fields'=>['content.show_nav'=>0]]],'acceptance'=>$diagnosis]));
guidanceCheck($parsed['acceptance']===$diagnosis&&$parsed['operations'][0]['type']==='configure_page','decision parser preserves complete explicit-false input-image diagnosis alongside repair operations');
$assetInstruction=D::independentAssetInstruction();
guidanceCheck(str_contains($assetInstruction,'approved_design')&&str_contains($assetInstruction,'visual_review')&&str_contains(D::visualReviewInstruction(),$assetInstruction),'implementation and visual review share the same approved-raster asset contract');
foreach(['形状','画风','材质','颜色','背景','可见bbox'] as $feature)guidanceCheck(str_contains($assetInstruction,$feature),'asset prompt derives actual approved appearance feature '.$feature);
guidanceCheck(str_contains($assetInstruction,'不能从页面主题')&&str_contains($assetInstruction,'3D')&&str_contains($assetInstruction,'玻璃')&&str_contains($assetInstruction,'金属')&&str_contains($assetInstruction,'除非批准图本身明确包含'),'flat reference cannot be restyled from theme while genuinely visible materials remain allowed');
guidanceCheck(str_contains($assetInstruction,'素材策略和来源授权')&&str_contains($assetInstruction,'既有匹配素材')&&str_contains($assetInstruction,'单元素')&&str_contains($assetInstruction,'禁止改变'),'reuse and single-element prompts preserve authorized strategy and explicit style locks');
guidanceCheck(str_contains($assetInstruction,'真实透明能力')&&str_contains($assetInstruction,'实际容器背景')&&str_contains($assetInstruction,'alpha')&&str_contains($assetInstruction,'图片留白')&&str_contains($assetInstruction,'rpx外壳'),'background/transparency and actual visible bounds are distinct from image canvas or rpx shell');
guidanceCheck(str_contains($assetInstruction,'同一素材URI不等于裁切正确')&&str_contains($assetInstruction,'image_fit=cover')&&str_contains($assetInstruction,'不能自动去掉图片自带黑条')&&str_contains($assetInstruction,'复用已成功素材')&&str_contains($assetInstruction,'不能编造裁剪字段'),'asset identity and real image-fit do not prove a matching crop or remove embedded bars');
$adaptation=D::componentAdaptationInstruction();
guidanceCheck(str_contains($adaptation,'approved_design')&&str_contains($adaptation,'visual_review')&&str_contains(D::visualReviewInstruction(),$adaptation),'implementation and visual review share an actual component-composition fallback policy');
guidanceCheck(str_contains($adaptation,'catalog')&&str_contains($adaptation,'names[]')&&str_contains($adaptation,'真实消费')&&str_contains($adaptation,'分解重组'),'unsupported geometry leads to real contract discovery and supported composition instead of endless outer-shell tuning');
foreach(['可编辑文字','已有素材','业务来源','合法交互','scope'] as $preserve)guidanceCheck(str_contains($adaptation,$preserve),'composition preserves existing authoring/safety boundary '.$preserve);
guidanceCheck(str_contains($adaptation,'禁止')&&str_contains($adaptation,'未支持')&&str_contains($adaptation,'不能修改批准设计')&&str_contains($adaptation,'不能虚假PASS'),'composition cannot invent parameters, alter the approved visual target or declare an unsupported match');
foreach(\app\common\service\decorate\agent\DecorationAgentCatalog::summary()['components'] as $component)guidanceCheck(!str_contains($adaptation,$component['name']),'generic fallback does not prescribe component '.$component['name']);
echo "visual review guidance: $n checks passed (real context/prompt services, no DB/provider writes)\n";
